"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2177],{82177:e=>{e.exports=JSON.parse('{"slug":"kurs-dollara-nizhe-83-rubley-nalogovyy-period-oktyabr-2026","locale":"es","title":"El d\xf3lar baja de 83 rublos pese a las mayores compras de divisas desde 2022","description":"El tipo oficial del 20 de octubre es 82,85 rublos, m\xednimo desde agosto. Por qu\xe9 el rublo mejora antes de los impuestos del 28 de octubre mientras Finanzas compra divisas.","blocks":[{"id":"b001","kind":"paragraph","text":"El Banco de Rusia fij\xf3 para el 20 de octubre un d\xf3lar de 82,85 rublos, 77 kopeks menos. No bajaba de 83 desde el 22 de agosto. El euro cay\xf3 a 93,23 y el yuan a 12,39. En el mercado extraburs\xe1til, el 19 de octubre el d\xf3lar lleg\xf3 a 82,56. A comienzos de mes ocurr\xeda lo contrario: el 7 de octubre, el oficial sub\xeda a 85,71. En 2 semanas, el rublo recuper\xf3 esa p\xe9rdida."},{"id":"b002","kind":"paragraph","text":"La debilidad del 7 de octubre se atribu\xeda a la regla presupuestaria. Finanzas reserva los ingresos petroleros extraordinarios en el Fondo Nacional de Bienestar comprando divisas y oro. Del 7 de octubre al 6 de noviembre destina 279,42 mil millones. Descontando las ventas del Banco de Rusia, el Estado compra 12,1 mil millones diarios, 6 veces septiembre y el mayor volumen desde enero de 2022."},{"id":"b003","kind":"paragraph","text":"Imagina un profesional que cobra en d\xf3lares y debe pagar el alquiler en rublos el d\xeda 28. Conserva las divisas durante medio mes y vende una suma grande una semana antes. As\xed act\xfaan los exportadores. Los impuestos de septiembre vencen el 28 de octubre. Los ingresos petroleros y gasistas de octubre se estiman en 1 bill\xf3n, 0,5 billones m\xe1s que septiembre, principalmente por el impuesto trimestral sobre ingresos adicionales, unos 0,36 billones. Por eso se llama periodo fiscal a la segunda mitad del mes."},{"id":"b004","kind":"paragraph","text":"Los analistas estiman ventas de los grandes exportadores en octubre por unos $4 mil millones. Las compras estatales al cambio actual suman unos $3,2 mil millones, repartidas entre 22 sesiones. Al final del mes, la oferta supera a la demanda. Ayudan factores externos: el \xedndice del d\xf3lar cay\xf3 el 19 de octubre un 1,2% desde su m\xe1ximo reciente y Estados Unidos aplaz\xf3 aranceles a compradores de petr\xf3leo ruso."},{"id":"b005","kind":"paragraph","text":"Para importaciones, viajes y transferencias al extranjero, el cambio es mejor que hace 2 semanas. Las tiendas lo reflejan con retraso porque compran antes. El tipo del 14% tambi\xe9n sostiene el rublo: cr\xe9dito caro, menor demanda importadora y dep\xf3sitos en rublos m\xe1s atractivos. A exportadores y presupuesto les perjudica: reciben menos rublos por cada barril vendido en divisas."},{"id":"b006","kind":"paragraph","text":"Vladimir Evstifeev, de Zenit, cree que el d\xf3lar podr\xeda acercarse a 82 rublos el 28 de octubre. Tras pagar impuestos, los exportadores necesitan menos moneda nacional y suelen reducir ventas, mientras Finanzas compra hasta el 6 de noviembre. El nuevo volumen se anunciar\xe1 a principios de noviembre seg\xfan el petr\xf3leo de octubre. Un crudo caro implica m\xe1s compras; uno barato reduce tanto las compras p\xfablicas como los ingresos exportadores."},{"id":"b007","kind":"heading","text":"\xbfPor qu\xe9 el d\xf3lar cae de 83 rublos en octubre de 2026?"},{"id":"b008","kind":"paragraph","text":"Las petroleras pagan los impuestos de septiembre antes del 28 de octubre. Los ingresos sectoriales de octubre rondar\xedan 1 bill\xf3n, el doble que septiembre. Para pagar venden divisas, cuya oferta supera las compras presupuestarias del Estado y fortalece al rublo."},{"id":"b009","kind":"heading","text":"\xbfPor qu\xe9 mejora el rublo si Finanzas compra divisas?"},{"id":"b010","kind":"paragraph","text":"El Estado compra cantidades iguales cada d\xeda, unos 12 mil millones de rublos. Los exportadores venden de forma desigual y concentran las ventas antes del vencimiento. En la segunda mitad del mes hay m\xe1s vendedores que compradores."},{"id":"b011","kind":"heading","text":"\xbfQu\xe9 pasar\xe1 despu\xe9s del 28 de octubre?"},{"id":"b012","kind":"paragraph","text":"Tras pagar impuestos, los exportadores necesitan menos rublos y suelen vender menos divisas. Las compras actuales de Finanzas siguen hasta el 6 de noviembre; el siguiente volumen depender\xe1 del petr\xf3leo de octubre."}],"sources":[{"label":"El d\xf3lar baja de 83 rublos por primera vez en dos meses","url":"https://www.kommersant.ru/doc/9042314"},{"label":"El d\xf3lar se acerca a 82,5 rublos","url":"https://www.kommersant.ru/doc/9042203"},{"label":"El banco central reduce el tipo del d\xf3lar","url":"https://lenta.ru/news/2026/10/19/tsb-ponizil-kurs-dollara"},{"label":"El Banco de Rusia reduce el d\xf3lar en 77 kopeks","url":"https://www.vedomosti.ru/finance/news/2026/10/19/1238342-kurs-dollara"},{"label":"Tipo del d\xf3lar del 8 de octubre de 2026","url":"https://ppt.ru/currencies/usd/08-10-2026"},{"label":"Los ingresos petroleros rusos llegar\xedan en octubre a 1 bill\xf3n","url":"https://ru.themoscowtimes.com/2026/10/15/neftegazovye-dokhody-byudzheta-rf-vyrastut-na-10-v-oktyabre-2625gg-do-1-trln-rub-raschyot-reyter-a208727"},{"label":"El rublo sigue subiendo con apoyo petrolero y fiscal","url":"https://ru.themoscowtimes.com/2026/10/19/rubl-prodolzhaet-rost-s-uchetom-neftyanoy-i-nalogovoy-podderzhki-geopolitiki-a208952"},{"label":"Finanzas comprar\xe1 divisas y oro por 279,42 mil millones del 7 de octubre al 6 de noviembre","url":"https://www.kommersant.ru/doc/9006327"}],"sourceBodySha256":"f25608d7c3546bcf7841b9396fc0c3e8ef4ad41fa20f369f655ea9a55be665d4"}')}}]);